INSERT INTO [TodoVentas].[dbo].[Articulo]([IdMarca],[Titulo],[IdCategoria],[Descripcion],[PalabrasRelacionArticulo],[MetaDescripcion],[MetaKeyWords],[UnidadVolumen],[UnidadMasa],[UnidadLongitud],[Tallas],[Colores],[EnLinea],[PreOrdenar],[Sabor],[Activo],[GarantiaMeses],[VideoYoutube],[UnidadPresentacion]) VALUES(10,'Acetaminofen Kirkland, 500 tabletas 500 mg',39,'Contenido: 500 Tabletas Características: Analgésico / antipirético, Comparación de Tylenol Extra Strength ingrediente activo ® Comparación de Tylenol Extra Strength ingrediente activo ® ** Información del Medicamento Ingrediente Activo (en cada cápsula) - Objetivo: Paracetamol 500 mg - analgésico / antipirético Usos: El alivio temporal de dolores menores debidos a: Dolor de cabeza Dolores musculares Dolor de espalda Artritis Dolor de muelas El resfriado común Los cólicos menstruales Reduce la fiebre Advertencias: Advertencia de sobredosis: Tomar más de la dosis recomendada puede causar problemas de salud graves, como daños en el hígado. En caso de sobredosis, obtenga ayuda médica o contacte un Centro de Control de Intoxicación inmediatamente. La atención médica inmediata es fundamental tanto para adultos como para niños, incluso si no presentan ningún signo o síntoma. Alcohol Advertencia: Si usted consume 3 o más bebidas alcohólicas al día, pregúntele a su médico si puedes tomar acetaminofén u otros analgésicos / antipiréticos. El acetaminofén puede causar lesiones hepáticas. No utilizar: Con cualquier otro producto que contenga acetaminofén Pare el uso y pregúntele a un doctor si: Enrojecimiento o hinchazón Se presentan síntomas nuevos La fiebre empeora o dura más de 3 días El dolor empeora o dura más de 10 días Si está embarazada o dando de amamantar: Consulte a un profesional antes de usarlo. Mantener fuera del alcance de los niños. Instrucciones: No use más cantidad que la indicada (consulta la advertencia de sobredosis) Adultos y niños mayores de 12 años: Tome 2 cápsulas cada 6 horas según sea necesario No tome más de 8 tabletas en 24 horas Menores de 12 años: No utilice este producto Extra Fuerte para adultos en niños menores de 12 años de edad, lo que proporcionará más de la dosis recomendada (sobredosis) y podría causar graves problemas de salud Otra información: Conservar a temperatura ambiente (59-86 grados Fahrenheit) Ingredientes inactivos: Cera de carnauba, croscarmelosa de sodio *, hipromelosa, polietilenglicol, povidona, Metabisulfito de Sodio *, * glicolato sódico de almidón, almidón, ácido esteárico * Puede contener uno o más de estos ingredientes Como este producto es diferente: No contiene aspirina y es poco probable que cause la irritación gástrica a menudo asociada con la aspirina, el naproxeno sódico o ibuprofeno. Puede ser utilizado por la mayoría de las personas con úlcera péptica, cuando se toma según las indicaciones de las condiciones recomendadas.','Acetaminfen, dolores menores, analgesico, antipiretico, tylenol, reduce la fiebre, Kirkland','El alivio temporal de dolores menores debidos a: Dolor de cabeza Dolores musculares Dolor de espalda Artritis Dolor de muelas El resfriado común Los cólicos menstruales Reduce la fiebre','acetaminofen, kirkland, acetaminofen americano, medellin, acetaminofen bogota, acetaminofen cali, analgesico, antipiretico, tylenol, reduce la fiebre, dolor de muelas, Acetaminofen medellin, Acetaminofen bogota, acetaminofen cali, acetaminofen barran',0,0,0,0,0,1,1,0,1,0,'',0)
