INSERT INTO [TodoVentas].[dbo].[Articulo]([IdMarca],[Titulo],[IdCategoria],[Descripcion],[PalabrasRelacionArticulo],[MetaDescripcion],[MetaKeyWords],[UnidadVolumen],[UnidadMasa],[UnidadLongitud],[Tallas],[Colores],[EnLinea],[PreOrdenar],[Sabor],[Activo],[GarantiaMeses],[VideoYoutube],[UnidadPresentacion]) VALUES(10,'Multi- Porpose Solution Kirkland 3 botellas x 16oz Solucion para Llentes de Contacto',39,'Incluye : 3 Botellas de 16 oz de contenido cada una Caja de lentes Solución multiusos que le ayuda a mantener los lentes de contacto limpios y confortables Desinfección: Kirkland Signature MPS promueve la desinfección mediante la eliminación, matando a una amplia gama de bacterias y microorganismos en sus lentes para proteger los ojos contra la infección. Elimina proteínas y escombros para limpiar a fondo sus lentes. GRATIS Disfrute de una caja de lente en cualquier momento con su compra Descripciones: MPS Kirkland Signature es una solución estéril, isotónica, tamponada, conservado con biguanida polihexametileno (0,0001%), un tampón de fosfato, Poloxamer 237, edetato disódico, cloruro de sodio, cloruro de potasio, y agua purificada. Kirkland Signature MPS no contiene clorhexidina o timerosal. Indicaciones: Kirkland Signature MPS está indicada para el cuidado de lentes de contacto blandas (hidrófilas). Utilice este producto, según lo recomendado por su ojo cuidado profesional, a: Químicamente desinfectar (no calor) Limpie Enjuague Tienda Retire la proteína Advertencias: Problemas con lentes de contacto y productos para el cuidado de lentes podrían provocar lesiones graves en el ojo. Es esencial que siga las instrucciones de su profesional del cuidado del ojo y todas las instrucciones de etiquetado para el uso y cuidado de sus lentes y productos de cuidado de las lentes, incluyendo el caso de la lente. Problemas de los ojos, incluyendo úlceras corneales, pueden desarrollar rápidamente y conducir a la pérdida de la visión. Precauciones : Evite la exposición al agua cuando se lleva y el cuidado de sus lentes de contacto. Nunca utilice agua del grifo. Deseche cualquier solución restante en su estuche de lentes antes de volver a desinfectar. Utilice siempre una solución fresca. Enjuague caja de lente y tapas con solución fresca después de cada uso ; secar boca abajo sobre una toalla limpia. No utilice agua no estéril para enjuagar la caja de lente . Lávese siempre las manos y luego se seca con una toalla limpia , libre de pelusa antes de manipular las lentes . Utilice la caja de lente incluido con Kirkland Signature MPS . Reemplace su estuche de lentes cada 1-3 meses . Mantenga el envase bien cerrado cuando no esté en uso . Almacenar a temperatura ambiente. Usar antes de la fecha de caducidad marcada en la botella y caja de cartón. DESCARTAR SOLUCIÓN 90 días después de abrir . Nunca use Kirkland Signature MPS con una unidad de desinfección térmica. Mantener fuera del alcance de los niños','Multi- Porpose Solution Kirkland, solucion multiproposito, limpieza lentes de contacto, lentes de contacto, kirkland','promueve la desinfección mediante la eliminación, matando a una amplia gama de bacterias y microorganismos en sus lentes para proteger los ojos contra la infección. Elimina proteínas y escombros para limpiar a fondo sus lentes','Multi- Porpose Solution Kirkland, solucion multiproposito, limpieza lentes de contacto, lentes de contacto, kirkland',0,0,0,0,0,1,1,0,1,0,'',0)
